155	/**
156	 * Parse LLM evaluation response
157	 */
158	export function parseEvaluation(response: string): EvaluationResult {
159	  try {
160	    // Extract JSON from response (in case there's markdown or text around it)
161	    const jsonMatch = response.match(/\{[\s\S]*\}/);
162	    if (!jsonMatch) {
163	      throw new Error("No JSON found in evaluation response");
164	    }
165	
166	    const parsed = JSON.parse(jsonMatch[0]);
167	
168	    // Validate structure
169	    if (!parsed.criteria || typeof parsed.overall !== "number") {
170	      throw new Error("Invalid evaluation structure");
171	    }
172	
173	    // Calculate overall if not provided or normalize
174	    const overall =
175	      parsed.overall ||
176	      (parsed.criteria.personaAlignment * 0.3 +
177	        parsed.criteria.visualQuality * 0.2 +
178	        parsed.criteria.uniqueness * 0.2 +
179	        parsed.criteria.coherence * 0.15 +
180	        parsed.criteria.usability * 0.15);
181	
182	    return {
183	      overall: Math.min(1, Math.max(0, overall)),
184	      criteria: {
185	        personaAlignment: Math.min(1, Math.max(0, parsed.criteria.personaAlignment)),
186	        visualQuality: Math.min(1, Math.max(0, parsed.criteria.visualQuality)),
187	        uniqueness: Math.min(1, Math.max(0, parsed.criteria.uniqueness)),
188	        coherence: Math.min(1, Math.max(0, parsed.criteria.coherence)),
189	        usability: Math.min(1, Math.max(0, parsed.criteria.usability)),
190	      },
191	      features: (parsed.features || [0, 0, 0]).map((f: number) =>
192	        Math.min(1, Math.max(-1, f))
193	      ),
194	      feedback: parsed.feedback || "",
195	      improvements: parsed.improvements || [],
196	      tags: parsed.tags || [],
197	    };
198	  } catch (error) {
199	    // Fallback evaluation
200	    console.warn("Failed to parse evaluation, using fallback:", error);
201	    return {
202	      overall: 0.5,
203	      criteria: {
204	        personaAlignment: 0.5,
205	        visualQuality: 0.5,
206	        uniqueness: 0.5,
207	        coherence: 0.5,
208	        usability: 0.5,
209	      },
210	      features: [0, 0.5, 0.5],
211	      feedback: "Parse error - manual review needed",
212	      improvements: ["Re-generate with clearer prompt"],
213	      tags: ["review-needed"],
214	    };
215	  }
216	}
