218	/**
219	 * Evaluate a batch of assets
220	 */
221	export async function evaluateBatch(
222	  persona: Persona,
223	  assets: Array<{ type: "svg" | "image" | "video"; prompt: string; content?: string } & Omit<EvaluateOptions, "assetType">>,
224	  evaluateFn: (system: string, user: string) => Promise<string>,
225	  config: Partial<EvaluatorConfig> = {}
226	): Promise<EvaluationResult[]> {
227	  const evaluations: EvaluationResult[] = [];
228	  const learnedPreferences = buildLearnedPreferencesDocument(persona.id);
229	
230	  for (const asset of assets) {
231	    if (["typesafe", "notorganic"].includes(resolveEvaluatorProvider(config))) {
232	      // Service/malformed-answer failures must not become fallback passing scores.
233	      evaluations.push(await evaluateWithTypeSafe(persona, { ...asset, assetType: asset.type, learnedPreferences }, config));
234	      continue;
235	    }
236	    const { system, user } = buildEvaluationPrompt(persona, {
237	      assetType: asset.type,
238	      prompt: asset.prompt,
239	      content: asset.content,
240	      learnedPreferences,
241	    });
242	
243	    try {
244	      const response = await evaluateFn(system, user);
245	      const result = parseEvaluation(response);
246	      evaluations.push(result);
247	    } catch (error) {
248	      console.error("Evaluation failed for asset:", error);
249	      evaluations.push({
250	        overall: 0.3,
251	        criteria: {
252	          personaAlignment: 0.3,
253	          visualQuality: 0.3,
254	          uniqueness: 0.3,
255	          coherence: 0.3,
256	          usability: 0.3,
257	        },
258	        features: [0, 0.5, 0.5],
259	        feedback: "Evaluation failed",
260	        improvements: ["Retry evaluation"],
261	        tags: ["failed"],
262	      });
263	    }
264	  }
265	
266	  return evaluations;
267	}
