269	/**
270	 * Create a weighted scoring function for QD integration
271	 */
272	export function createScorer(
273	  weights: Partial<EvaluationCriteria> = {}
274	): (result: EvaluationResult) => number {
275	  const defaultWeights: EvaluationCriteria = {
276	    personaAlignment: 0.3,
277	    visualQuality: 0.2,
278	    uniqueness: 0.2,
279	    coherence: 0.15,
280	    usability: 0.15,
281	  };
282	
283	  const w = { ...defaultWeights, ...weights };
284	
285	  return (result: EvaluationResult) => {
286	    // Reject even when QD's qualityThreshold is zero; a hard gate cannot average away.
287	    if (result.gate?.accepted === false) return Number.NEGATIVE_INFINITY;
288	    return (
289	      result.criteria.personaAlignment * w.personaAlignment +
290	      result.criteria.visualQuality * w.visualQuality +
291	      result.criteria.uniqueness * w.uniqueness +
292	      result.criteria.coherence * w.coherence +
293	      result.criteria.usability * w.usability
294	    );
295	  };
296	}
