94	export async function generateAssetSuite(
95	  persona: Persona,
96	  assetTypes: AssetType[],
97	  config: BasteConfig,
98	  hooks: GenerationHooks = {},
99	): Promise<AssetSuite> {
100	  const log = hooks.log ?? console.log;
101	  const startTime = Date.now();
102	  const generator = new AssetGenerator(config.generation);
103	  const evaluations: EvaluationResult[] = [];
104	  const candidates: QDCandidate[] = [];
105	  const finalScores: Record<string, EvaluationResult> = {};
106	  const evaluatorProvider = resolveEvaluatorProvider(config.evaluator);
107	  // Surface missing credentials to the GUI before generating paid assets.
108	  if (assetTypes.some(a => a.kind === "video") && (config.generation.videoProvider ?? "seedance") === "seedance"
109	      && !config.generation.videoApiKey && !process.env.ARK_API_KEY) {
110	    throw new Error("Seedance needs ARK_API_KEY");
111	  }
112	  const needsFal = evaluatorProvider === "fal"
113	    || (config.generation.imageProvider === "fal" && assetTypes.some(a => a.kind === "image"))
114	    || (config.generation.svgProvider === "fal" && assetTypes.some(a => a.kind === "svg"))
115	    || (config.generation.videoProvider === "fal" && assetTypes.some(a => a.kind === "video"));
116	  if (needsFal && !config.generation.falApiKey && !process.env.FAL_KEY) {
117	    throw new Error("fal needs FAL_KEY");
118	  }
119	
120	  log(`\n🎨 Baste: Generating assets for "${persona.name}"`);
121	  log(`   Persona: ${persona.summary}`);
122	  log(`   Asset types: ${assetTypes.map((a) => a.kind).join(", ")}`);
123	
124	  // Generate prompts for each asset type
125	  const promptsByAsset = new Map<AssetType, Record<string, GeneratedPrompt>>();
126	  for (const asset of assetTypes) {
127	    promptsByAsset.set(asset, generatePrompts(persona, asset));
128	  }
129	
130	  // Run QD evolution for image assets (most impactful for UI)
131	  const imageAssets = assetTypes.filter((a) => a.kind === "image");
132	  let archive: QDArchive<string> = createArchive(config.qd);
133	
134	  if (imageAssets.length > 0) {
135	    log("\n🧬 Starting QD evolution for images...");
136	
137	    const imageAsset = imageAssets[0];
138	    const prompts = promptsByAsset.get(imageAsset)!;
139	
140	    archive = await runQD<string>(
141	      { ...config.qd, log },
142	      // Seed generation
143	      async () => ({
144	        genome: prompts.image.prompt,
145	        quality: 0,
146	        features: [0, 0, 0],
147	        generation: 0,
148	      }),
149	      // Mutation
150	      async (parent, rate) => ({
151	        genome: mutatePrompt(parent.genome, persona, rate),
152	        quality: 0,
153	        features: [0, 0, 0],
154	        generation: 0,
155	      }),
156	      // Evaluation
157	      async (genome, { generation }) => {
158	        // Generate the asset
159	        const asset = await generator.generate(persona, imageAsset, {
160	          ...prompts.image,
161	          prompt: genome,
162	        });
163	
164	        // Evaluate with LLM judge
165	        const evalResults = await evaluateBatch(
166	          persona,
167	          [
168	            {
169	              type: "image",
170	              prompt: genome,
171	              content: asset.content,
172	              purpose: imageAsset.purpose,
173	              metadata: asset.metadata,
174	              suite: assetTypes.map(a => ({ type: a.kind, purpose: a.purpose, prompt: promptsByAsset.get(a)![a.kind].prompt })),
175	            },
176	          ],
177	          // Evaluation function: a vision model on fal, or OpenAI over the prompt
178	          async (system, user) => {
179	            if (evaluatorProvider === "fal") {
180	              return judgeWithFal(system, user, { model: config.evaluator.model, apiKey: config.evaluator.apiKey, temperature: config.evaluator.temperature, imageUrl: asset.metadata.sourceUrl });
181	            }
182	            const apiKey = config.evaluator.apiKey || process.env.OPENAI_API_KEY;
183	            if (!apiKey) {
184	              console.warn("[baste] No OPENAI_API_KEY set — using rule-based heuristic evaluation (set OPENAI_API_KEY or evaluator.apiKey for LLM judge)");
185	              // Local heuristic: score based on prompt richness and persona keyword overlap.
186	              // Ensures the archive is still useful even without an LLM API key.
187	              const keywords = [...persona.aesthetic.visualKeywords, ...persona.aesthetic.moodKeywords];
188	              const promptWords = genome.toLowerCase().split(/[^a-z]+/);
189	              const overlap = keywords.filter(k => promptWords.includes(k.toLowerCase())).length;
190	              const normOverlap = keywords.length ? Math.min(1, overlap / Math.max(1, keywords.length * 0.3)) : 0.5;
191	              const richness = Math.min(1, promptWords.filter(w => w.length > 3).length / 20);
192	              const baseScore = 0.4 + (normOverlap * 0.35) + (richness * 0.15);
193	              const paScore = Math.min(1, baseScore + 0.05 * Math.random());
194	              const vqScore = Math.min(1, 0.5 + richness * 0.4 + 0.05 * Math.random());
195	              const unScore = Math.min(1, 0.45 + normOverlap * 0.45 + 0.05 * Math.random());
196	              const coScore = Math.min(1, 0.5 + 0.3 * richness + 0.05 * Math.random());
197	              const usScore = Math.min(1, 0.55 + 0.3 * normOverlap + 0.05 * Math.random());
198	              const overall = paScore * 0.3 + vqScore * 0.2 + unScore * 0.2 + coScore * 0.15 + usScore * 0.15;
199	              return JSON.stringify({
200	                overall,
201	                criteria: {
202	                  personaAlignment: +paScore.toFixed(3),
203	                  visualQuality: +vqScore.toFixed(3),
204	                  uniqueness: +unScore.toFixed(3),
205	                  coherence: +coScore.toFixed(3),
206	                  usability: +usScore.toFixed(3),
207	                },
208	                features: [
209	                  +(Math.random() * 2 - 1).toFixed(3),
210	                  +richness.toFixed(3),
211	                  +normOverlap.toFixed(3),
212	                ],
213	                feedback: `Local heuristic evaluation: prompt-keyword overlap=${(normOverlap * 100).toFixed(0)}%, prompt richness=${(richness * 100).toFixed(0)}%. ` +
214	                  (normOverlap > 0.5 ? "Strong persona alignment" : normOverlap > 0.2 ? "Moderate persona alignment, consider more persona keywords" : "Weak persona alignment, refine prompt"),
215	                improvements: [
216	                  "Add API key for LLM judge (OPENAI_API_KEY)",
217	                  normOverlap < 0.5 ? `Inject more ${persona.aesthetic.visualKeywords.slice(0,3).join(", ")} keywords` : "Explore contrasting moods for diversity",
218	                  richness < 0.5 ? "Expand prompt with detail: lighting, materials, composition" : "Experiment with shorter, punchier prompts",
219	                ],
220	                tags: ["heuristic", normOverlap > 0.5 ? "aligned" : "needs-work", richness > 0.5 ? "rich" : "sparse", "local-eval"],
221	              });
222	            }
223	
224	            const response = await fetch("https://api.openai.com/v1/chat/completions", {
225	              method: "POST",
226	              headers: {
227	                Authorization: `Bearer ${apiKey}`,
228	                "Content-Type": "application/json",
229	              },
230	              body: JSON.stringify({
231	                model: config.evaluator.model,
232	                messages: [
233	                  { role: "system", content: system },
234	                  { role: "user", content: user },
235	                ],
236	                temperature: 0.3,
237	              }),
238	            });
239	
240	            const data = await response.json();
241	            return data.choices[0]?.message?.content || "";
242	          },
243	          config.evaluator
244	        );
245	
246	        const result = evalResults[0];
247	        evaluations.push(result);
248	        const scorer = createScorer(config.evaluator.weights);
249	        const quality = scorer(result);
250	        const candidate: QDCandidate = {
251	          generation, path: asset.content, sourceUrl: asset.metadata.sourceUrl, quality,
252	          features: result.features, criteria: result.criteria, feedback: result.feedback,
253	        };
254	        candidates.push(candidate);
255	        hooks.candidate?.(candidate);
256	        log(`   Candidate ${candidates.length} (generation ${generation}) judged ${quality.toFixed(2)}`);
257	
258	        return {
259	          quality,
260	          features: result.features,
261	        };
262	      }
263	    );
264	    // Record which candidates hold a cell in the final archive.
265	    for (const [cell, solution] of archive.cells) {
266	      const held = candidates.find((c) => c.quality === solution.quality && c.features.every((f, i) => f === solution.features[i]));
267	      if (held) held.cell = cell;
268	    }
269	  }
270	
271	  // Generate final diverse assets from archive
272	  log("\n🎯 Generating final assets...");
273	  const diversePrompts = imageAssets.length > 0 ? getDiverseSamples(archive, config.outputCount)
274	    : [{ genome: "", quality: 0, features: [0, 0, 0], generation: 0 }];
275	
276	  const finalAssets: GeneratedAsset[] = [];
277	
278	  for (const solution of diversePrompts) {
279	    for (const assetType of assetTypes) {
280	      try {
281	        const originalPrompt = promptsByAsset.get(assetType)![assetType.kind];
282	        // Only the evolved asset takes the evolved genome. Other images keep their own
283	        // brief: a hero must not be drawn from the background's prompt.
284	        const evolved = assetType === imageAssets[0] && solution.genome;
285	        const asset = await generator.generate(persona, assetType, {
286	          ...originalPrompt,
287	          prompt: evolved ? solution.genome : originalPrompt.prompt,
288	        });
289	        if (evaluatorProvider === "fal") {
290	          // The judge looks at images and rendered SVG; videos are judged on their brief.
291	          const imageUrl = asset.type === "image" ? asset.metadata.sourceUrl : asset.type === "svg" ? svgPreview(asset.content) : undefined;
292	          const [evaluation] = await evaluateBatch(persona, [{
293	            type: asset.type, prompt: asset.prompt, content: imageUrl ? undefined : asset.content,
294	            purpose: assetType.purpose, metadata: asset.metadata,
295	          }], (system, user) => judgeWithFal(system, user, {
296	            model: config.evaluator.model, apiKey: config.evaluator.apiKey, temperature: config.evaluator.temperature, imageUrl,
297	          }), config.evaluator);
298	          evaluations.push(evaluation);
299	          finalScores[asset.id] = evaluation;
300	        }
301	        if (evaluatorProvider === "typesafe" || evaluatorProvider === "notorganic") {
302	          const [evaluation] = await evaluateBatch(persona, [{
303	            type: asset.type, prompt: asset.prompt, content: asset.content,
304	            purpose: assetType.purpose, metadata: asset.metadata,
305	            suite: finalAssets.map(a => ({ type: a.type, purpose: a.metadata.assetPurpose, prompt: a.prompt, metadata: a.metadata })),
306	          }], async () => { throw new Error("Unexpected OpenAI evaluator selection"); }, config.evaluator);
307	          evaluations.push(evaluation);
308	          finalScores[asset.id] = evaluation;
309	          if (evaluation.gate?.accepted === false) continue;
310	        }
311	        finalAssets.push(asset);
312	      } catch (error) {
313	        log(`Failed to generate ${assetType.kind}: ${error instanceof Error ? error.message : String(error)}`);
314	        if (assetType.kind === "video" || evaluatorProvider === "typesafe" || evaluatorProvider === "notorganic" || config.generation.imageProvider === "notorganic") throw error;
315	      }
316	    }
317	  }
318	
319	  // Categorize by type
320	  const svgs = finalAssets.filter((a) => a.type === "svg");
321	  const images = finalAssets.filter((a) => a.type === "image");
322	  const videos = finalAssets.filter((a) => a.type === "video");
323	
324	  const duration = Date.now() - startTime;
325	
326	  log(`\n✅ Asset suite complete for "${persona.name}"`);
327	  log(`   Generated: ${svgs.length} SVGs, ${images.length} images, ${videos.length} videos`);
328	  log(`   Time: ${(duration / 1000).toFixed(1)}s`);
329	
330	  return {
331	    persona,
332	    assets: { svgs, images, videos },
333	    archive,
334	    evaluations,
335	    candidates,
336	    finalScores,
337	    metadata: {
338	      generationDuration: duration,
339	      totalIterations: config.qd.iterations,
340	      coverage: archive.coverage,
341	    },
342	  };
343	}
