385	      description: `Hero banner image in the style of ${persona.influences.films[0] || "concept art"}`,
386	      constraints: { aspectRatio: "21:9" },
387	    },
388	    {
389	      kind: "video",
390	      purpose: "animation",
391	      description: `Ambient motion background loop inspired by ${persona.influences.music.genres[0] || "ambient music"}`,
392	      constraints: { aspectRatio: "16:9" },
393	    },
394	  ];
395	
396	  return generateAssetSuite(persona, uiComponents, config, hooks);
397	}
