185	/**
186	 * Build a complete BasteConfig (for the orchestrator) from a user config.
187	 * Optional overrides allow per-request provider/model selection from the GUI.
188	 */
189	export function toBasteConfig(
190	  userConfig: BasteUserConfig,
191	  overrides?: GenerationOverrides
192	): {
193	  generation: GenerationConfig;
194	  qd: QDConfig;
195	  outputCount: number;
196	  evaluator: EvaluatorConfig;
197	} {
198	  const qdCfg = { ...defaultConfig.qd, ...(userConfig.qd || {}) };
199	  const evalCfg = { ...defaultConfig.evaluator, ...(userConfig.evaluator || {}) };
200	  const imgCfg = userConfig.generators?.image ?? defaultConfig.generators.image;
201	  const svgCfg = userConfig.generators?.svg ?? defaultConfig.generators.svg;
202	  const vidCfg = userConfig.generators?.video ?? defaultConfig.generators.video;
203	
204	  const imageProvider = (overrides?.imageProvider ?? imgCfg?.provider ?? "openai") as "openai" | "gemini" | "notorganic" | "fal";
205	  if (!["openai", "gemini", "notorganic", "fal"].includes(imageProvider)) throw new Error(`Unsupported image provider: ${imageProvider}`);
206	  // Saved configs may name SVG providers that were never implemented; those keep using QuiverAI.
207	  if (overrides?.svgProvider && !["quiver", "fal"].includes(overrides.svgProvider)) throw new Error(`Unsupported SVG provider: ${overrides.svgProvider}`);
208	  const svgProvider: "quiver" | "fal" = (overrides?.svgProvider ?? svgCfg?.provider) === "fal" ? "fal" : "quiver";
209	  const imageModel = overrides?.imageModel ?? (imageProvider === imgCfg?.provider ? imgCfg.model : undefined);
210	  const videoProvider = overrides?.videoProvider ?? vidCfg?.provider ?? "seedance";
211	  if (!["seedance", "veo", "fal", "runway", "local"].includes(videoProvider)) {
212	    throw new Error(`Unsupported video provider: ${videoProvider}`);
213	  }
214	  const videoModel = overrides?.videoModel ?? (videoProvider === vidCfg?.provider ? vidCfg.model : undefined);
215	  const videoApiKey = (videoProvider === vidCfg?.provider ? vidCfg.apiKey : undefined) ??
216	    (videoProvider === "seedance" ? process.env.ARK_API_KEY : videoProvider === "veo" ? process.env.GOOGLE_API_KEY : videoProvider === "fal" ? process.env.FAL_KEY : undefined);
217	  const evaluatorProvider = overrides?.evaluatorProvider ?? resolveEvaluatorProvider(userConfig.evaluator);
218	  // A saved model or key belongs to the saved provider; never hand it to a different one.
219	  const savedEvaluator = !overrides?.evaluatorProvider || overrides.evaluatorProvider === userConfig.evaluator?.provider;
220	
221	  // Resolve the right API key for the chosen image provider
222	  const imageApiKey = (imageProvider === imgCfg?.provider ? imgCfg.apiKey : undefined) ??
223	    (imageProvider === "gemini"
224	      ? process.env.GOOGLE_API_KEY
225	      : imageProvider === "fal" ? process.env.FAL_KEY : process.env.OPENAI_API_KEY);
226	  // fal-backed providers share one key; the first configured one wins.
227	  const falApiKey = [
228	    imageProvider === "fal" && imgCfg?.provider === "fal" ? imgCfg.apiKey : undefined,
229	    svgProvider === "fal" && svgCfg?.provider === "fal" ? svgCfg.apiKey : undefined,
230	    videoProvider === "fal" && vidCfg?.provider === "fal" ? vidCfg.apiKey : undefined,
231	  ].find(Boolean) ?? process.env.FAL_KEY;
232	
233	  return {
234	    generation: {
235	      outputDir: userConfig.outputDir ?? defaultConfig.outputDir,
236	      imageProvider,
237	      imageModel,
238	      imageSize: imgCfg?.size,
239	      imageQuality: imgCfg?.quality,
240	      imageStyle: imgCfg?.style,
241	      openaiApiKey: imageProvider === "openai" ? imageApiKey : undefined,
242	      googleApiKey: imageProvider === "gemini" ? imageApiKey : process.env.GOOGLE_API_KEY,
243	      falApiKey,
244	      svgProvider,
245	      svgModel: svgProvider === svgCfg?.provider ? svgCfg?.model : undefined,
246	      videoProvider: videoProvider as GenerationConfig["videoProvider"],
247	      videoModel,
248	      videoApiKey,
249	      videoBaseUrl: videoProvider === vidCfg?.provider ? vidCfg.baseUrl : undefined,
250	      videoDuration: vidCfg?.duration,
251	      videoRatio: vidCfg?.ratio,
252	      videoResolution: vidCfg?.quality,
253	      quiverApiKey: svgCfg?.apiKey ?? process.env.QUIVER_API_KEY,
254	      quiverBaseUrl: svgCfg?.baseUrl,
255	    },
256	    qd: {
257	      features: qdCfg.features!,
258	      iterations: qdCfg.iterations!,
259	      batchSize: qdCfg.batchSize!,
260	      mutationRate: qdCfg.mutationRate!,
261	      qualityThreshold: qdCfg.qualityThreshold!,
262	    },
263	    outputCount: userConfig.outputCount ?? defaultConfig.outputCount,
264	    evaluator: {
265	      provider: evaluatorProvider,
266	      model: (savedEvaluator ? userConfig.evaluator?.model : undefined)
267	        ?? { notorganic: "judgement", typesafe: "jev-latest", fal: "google/gemini-2.5-flash" }[evaluatorProvider as string]
268	        ?? defaultConfig.evaluator.model,
269	      apiKey: (savedEvaluator ? evalCfg.apiKey : undefined)
270	        ?? (evaluatorProvider === "typesafe" ? process.env.TYPESAFE_API_KEY : evaluatorProvider === "fal" ? falApiKey : process.env.OPENAI_API_KEY),
271	      baseUrl: savedEvaluator ? evalCfg.baseUrl : undefined,
272	      temperature: evalCfg.temperature,
273	      weights: evalCfg.weights,
274	    },
275	  };
276	}
