278	/**
279	 * Load config from a JSON file.
280	 */
281	export function loadConfigFile(path: string): BasteUserConfig {
282	  const resolved = resolve(path);
283	  if (!existsSync(resolved)) {
284	    return {};
285	  }
286	  try {
287	    return JSON.parse(readFileSync(resolved, "utf-8"));
288	  } catch {
289	    console.warn(`Failed to parse config file: ${resolved}`);
290	    return {};
291	  }
292	}
293	
294	/**
295	 * Load config with standard resolution order:
296	 * 1. Explicit file (if provided)
297	 * 2. baste.config.json in cwd
298	 * 3. .bastec.json in cwd
299	 * 4. Default config
300	 */
301	export function resolveConfig(explicitPath?: string): BasteUserConfig {
302	  if (explicitPath) {
303	    return loadConfigFile(explicitPath);
304	  }
305	  const fromJson = loadConfigFile("./baste.config.json");
306	  if (Object.keys(fromJson).length > 0) return fromJson;
307	  const fromDot = loadConfigFile("./.bastec.json");
308	  if (Object.keys(fromDot).length > 0) return fromDot;
309	  return {};
310	}
311	
312	/**
313	 * Save config to a JSON file.
314	 */
315	export function saveConfigFile(config: BasteUserConfig, path: string): void {
316	  const resolved = resolve(path);
317	  writeFileSync(resolved, JSON.stringify(config, null, 2));
318	}
