1	/**
2	 * Asset Generation Services
3	 *
4	 * SVG: QuiverAI (QUIVER_API_KEY), or Recraft vector on fal (FAL_KEY).
5	 * Image: OpenAI (gpt-image-2.5 / gpt-image-2 / dall-e-3), Google Gemini, or any fal image model.
6	 * Video: Seedance via BytePlus ModelArk, Veo via Google API, or Seedance/Kling on fal.
7	 */
8	
9	import { writeFileSync, mkdirSync } from "node:fs";
10	import type { AestheticProfile, Persona } from "../persona/types.js";
11	import type { AssetType, GeneratedPrompt } from "../generation/prompts.js";
12	import { assertSafePublicUrl } from "../shared/url.js";
13	import { generateDesignTokens } from "./design-system.js";
14	import { falDownload, falRun, sizeForRatio } from "./fal.js";
15	
16	export interface GeneratedAsset {
17	  id: string;
18	  type: "svg" | "image" | "video";
19	  content: string;
20	  prompt: string;
21	  metadata: {
22	    service: string;
23	    model: string;
24	    personaId: string;
25	    assetPurpose: string;
26	    seed?: number;
27	    generationTime: number;
28	    /** Provider-hosted original, kept for provenance and for judges that look at pixels. */
29	    sourceUrl?: string;
30	  };
31	}
32	
33	export interface GenerationConfig {
34	  openaiApiKey?: string;
35	  quiverApiKey?: string;
36	  quiverBaseUrl?: string;
37	  googleApiKey?: string;
38	  /** One key for every fal-backed provider. */
39	  falApiKey?: string;
40	  outputDir: string;
41	  svgProvider?: "quiver" | "fal";
42	  svgModel?: string;
43	  imageProvider?: "openai" | "gemini" | "notorganic" | "fal";
44	  /** Request-scoped, server-held Not Organic authorization. Never serialized. */
45	  notOrganicFetch?: (path: string, init?: RequestInit) => Promise<Response>;
46	  imageModel?: string;
47	  imageSize?: string;
48	  imageQuality?: "standard" | "high";
49	  imageStyle?: "vivid" | "natural";
50	  videoProvider?: "seedance" | "veo" | "runway" | "local" | "fal";
51	  videoModel?: string;
52	  videoApiKey?: string;
