60	
61	// ── QuiverAI SVG Generator ────────────────────────────────────────────────────
62	
63	/** Recraft's vector substyles closest to each icon style. */
64	const RECRAFT_VECTOR_STYLE: Record<AestheticProfile["iconStyle"], string> = {
65	  line: "vector_illustration/line_art",
66	  filled: "vector_illustration/vivid_shapes",
67	  "hand-drawn": "vector_illustration/marker_outline",
68	  geometric: "vector_illustration/segmented_colors",
69	  abstract: "vector_illustration",
70	};
71	
72	export class SVGGenerator {
73	  private apiKey: string | undefined;
74	  private baseUrl: string;
75	  private outputDir: string;
76	  private provider: "quiver" | "fal";
77	  private falKey: string | undefined;
78	  private falModel: string;
79	
80	  constructor(config: GenerationConfig) {
81	    this.apiKey = config.quiverApiKey || process.env.QUIVER_API_KEY;
82	    this.baseUrl = config.quiverBaseUrl || process.env.QUIVER_BASE_URL || "https://api.quiverai.com";
83	    this.provider = config.svgProvider ?? "quiver";
84	    this.falKey = config.falApiKey;
85	    this.falModel = config.svgModel ?? "fal-ai/recraft/v3/text-to-image";
86	    this.outputDir = `${config.outputDir}/svg`;
87	    mkdirSync(this.outputDir, { recursive: true });
88	  }
89	
90	  async generate(persona: Persona, asset: AssetType, prompt: GeneratedPrompt): Promise<GeneratedAsset> {
91	    if (this.provider === "fal") return this.generateFal(persona, asset, prompt);
92	    if (!this.apiKey) {
93	      throw new Error(
94	        "QuiverAI API key required for SVG generation. Set QUIVER_API_KEY environment variable or configure generators.svg.apiKey in baste.config.json."
95	      );
96	    }
97	
98	    const startTime = Date.now();
99	    const id = `${persona.id}-${asset.purpose}-${stamp()}`;
100	
101	    const svgContent = await this.callQuiverAPI(prompt);
102	
103	    const outputPath = `${this.outputDir}/${id}.svg`;
104	    writeFileSync(outputPath, svgContent);
105	
106	    return {
107	      id,
108	      type: "svg",
109	      content: outputPath,
110	      prompt: prompt.prompt,
111	      metadata: {
112	        service: "quiverai",
113	        model: "quiver-1",
114	        personaId: persona.id,
115	        assetPurpose: asset.purpose,
116	        generationTime: Date.now() - startTime,
117	      },
118	    };
119	  }
120	
121	  /**
122	   * Recraft V3 draws real vector output. The persona's own palette goes in as
123	   * preferred colours, so icons arrive already dressed in its tokens.
124	   * https://fal.ai/models/fal-ai/recraft/v3/text-to-image/api
125	   */
126	  private async generateFal(persona: Persona, asset: AssetType, prompt: GeneratedPrompt): Promise<GeneratedAsset> {
127	    const startTime = Date.now();
128	    const id = `${persona.id}-${asset.purpose}-${stamp()}`;
129	    const { colors } = generateDesignTokens(persona);
130	    const palette = [colors.primary, colors.secondary, colors.accent, colors.background].map(hexToRgb).filter((c) => c !== null);
131	    const result = await falRun<{ images?: Array<{ url?: string; content_type?: string }> }>(this.falModel, {
132	      // Recraft caps prompts at 1,000 characters. The engine's SVG brief ends in
133	      // instructions for code-writing models, which a drawing model does not need.
134	      prompt: clipPrompt(prompt.prompt.replace(/\n?Output as clean SVG code[^\n]*/, ""), 1000),
135	      style: RECRAFT_VECTOR_STYLE[persona.aesthetic.iconStyle] ?? "vector_illustration",
136	      image_size: "square_hd",
137	      colors: palette,
138	    }, { key: this.falKey });
139	    const image = result.images?.[0];
140	    if (!image?.url || (image.content_type && image.content_type !== "image/svg+xml")) throw new Error("fal returned no SVG.");
141	    const outputPath = `${this.outputDir}/${id}.svg`;
142	    const sourceUrl = await falDownload(image.url, outputPath, 5 * 1024 * 1024);
143	    return {
144	      id,
145	      type: "svg",
146	      content: outputPath,
147	      prompt: prompt.prompt,
148	      metadata: { service: "fal", model: this.falModel, personaId: persona.id, assetPurpose: asset.purpose, generationTime: Date.now() - startTime, sourceUrl },
149	    };
150	  }
151	
152	  private async callQuiverAPI(prompt: GeneratedPrompt): Promise<string> {
153	    const response = await fetch(`${this.baseUrl}/v1/svg/generate`, {
154	      method: "POST",
155	      headers: {
156	        Authorization: `Bearer ${this.apiKey}`,
157	        "Content-Type": "application/json",
158	      },
159	      body: JSON.stringify({
160	        prompt: prompt.prompt,
161	        style: prompt.systemContext,
162	        format: "svg",
163	        parameters: prompt.parameters,
164	      }),
165	    });
166	
167	    if (!response.ok) {
168	      const body = await response.text().catch(() => "");
169	      throw new Error(`QuiverAI API error ${response.status}: ${body || response.statusText}`);
170	    }
171	
172	    const data = await response.json();
173	
174	    // QuiverAI returns SVG either as `svg`, `content`, or `data.svg`
175	    const svgContent: string = data.svg ?? data.content ?? data.data?.svg ?? "";
176	    if (!svgContent || !svgContent.includes("<svg")) {
177	      throw new Error("QuiverAI returned an empty or invalid SVG response.");
178	    }
179	    return svgContent;
180	  }
181	}
182	
183	// ── Image Generator (OpenAI or Gemini) ───────────────────────────────────────
184	
185	export class ImageGenerator {
186	  private openaiKey: string | undefined;
187	  private googleKey: string | undefined;
188	  private falKey: string | undefined;
189	  private provider: "openai" | "gemini" | "notorganic" | "fal";
190	  private notOrganicFetch?: GenerationConfig["notOrganicFetch"];
191	  private model: string;
192	  private size: string;
193	  private quality: "standard" | "high";
194	  private style: "vivid" | "natural";
195	  private outputDir: string;
196	
197	  constructor(config: GenerationConfig) {
198	    this.openaiKey = config.openaiApiKey || process.env.OPENAI_API_KEY;
199	    this.googleKey = config.googleApiKey || process.env.GOOGLE_API_KEY;
200	    this.falKey = config.falApiKey;
201	    this.provider = config.imageProvider ?? "openai";
202	    this.notOrganicFetch = config.notOrganicFetch;
203	    this.model = config.imageModel ?? {
204	      notorganic: "image",
205	      gemini: "imagen-3.0-generate-002",
206	      fal: "fal-ai/bytedance/seedream/v4/text-to-image",
207	      openai: "gpt-image-2.5",
208	    }[this.provider];
209	    this.size = config.imageSize ?? "1024x1024";
210	    this.quality = config.imageQuality ?? "high";
211	    this.style = config.imageStyle ?? "vivid";
212	    this.outputDir = `${config.outputDir}/images`;
213	    mkdirSync(this.outputDir, { recursive: true });
214	  }
215	
216	  async generate(persona: Persona, asset: AssetType, prompt: GeneratedPrompt): Promise<GeneratedAsset> {
217	    const startTime = Date.now();
218	    const id = `${persona.id}-${asset.purpose}-${stamp()}`;
219	
220	    let outputPath: string;
221	    let service: string;
222	    let sourceUrl: string | undefined;
223	
224	    if (this.provider === "fal") {
225	      ({ outputPath, sourceUrl } = await this.generateFal(asset, prompt, id));
226	      service = "fal";
227	    } else if (this.provider === "notorganic") {
228	      if (!this.notOrganicFetch) throw new Error("Sign in to Not Organic before generating hosted images.");
229	      outputPath = `${this.outputDir}/${id}.png`;
230	      await this.generateNotOrganic(prompt, outputPath);
231	      service = "notorganic";
232	    } else if (this.provider === "gemini") {
233	      if (!this.googleKey) {
234	        throw new Error(
235	          "Google API key required for Gemini image generation. Set GOOGLE_API_KEY environment variable or configure generators.image.apiKey."
236	        );
237	      }
238	      outputPath = `${this.outputDir}/${id}.png`;
239	      await this.generateGemini(prompt, outputPath);
240	      service = "google";
241	    } else {
242	      if (!this.openaiKey) {
243	        throw new Error(
244	          "OpenAI API key required for image generation. Set OPENAI_API_KEY environment variable or configure generators.image.apiKey."
245	        );
246	      }
247	      outputPath = `${this.outputDir}/${id}.png`;
248	      await this.generateOpenAI(prompt, outputPath);
249	      service = "openai";
250	    }
251	
252	    return {
253	      id,
254	      type: "image",
255	      content: outputPath,
256	      prompt: prompt.prompt,
257	      metadata: {
258	        service,
259	        model: this.model,
260	        personaId: persona.id,
261	        assetPurpose: asset.purpose,
262	        generationTime: Date.now() - startTime,
263	        ...(sourceUrl ? { sourceUrl } : {}),
264	      },
