268	  /** Any fal text-to-image model that takes `image_size` and returns `images[]`. */
269	  private async generateFal(asset: AssetType, prompt: GeneratedPrompt, id: string): Promise<{ outputPath: string; sourceUrl: string }> {
270	    const ratio = asset.constraints?.aspectRatio ?? (typeof prompt.parameters?.aspectRatio === "string" ? prompt.parameters.aspectRatio : undefined);
271	    const result = await falRun<{ images?: Array<{ url?: string; content_type?: string }> }>(this.model, {
272	      prompt: prompt.prompt,
273	      image_size: sizeForRatio(ratio),
274	      num_images: 1,
275	      enable_safety_checker: true,
276	    }, { key: this.falKey });
277	    const image = result.images?.[0];
278	    if (!image?.url) throw new Error("fal returned no image.");
279	    const extension = { "image/jpeg": "jpg", "image/webp": "webp" }[image.content_type ?? ""] ?? "png";
280	    const outputPath = `${this.outputDir}/${id}.${extension}`;
281	    return { outputPath, sourceUrl: await falDownload(image.url, outputPath, 40 * 1024 * 1024) };
282	  }
