284	  private async generateNotOrganic(prompt: GeneratedPrompt, outputPath: string): Promise<void> {
285	    if (this.model !== "image") throw new Error("Choose the available Not Organic image model.");
286	    const response = await this.notOrganicFetch!("/v1/images/generations", {
287	      method: "POST",
288	      headers: { "Content-Type": "application/json" },
289	      signal: AbortSignal.timeout(180_000),
290	      body: JSON.stringify({ model: this.model, prompt: prompt.prompt, size: prompt.parameters?.size ?? this.size, n: 1 }),
291	    });
292	    if (!response.ok) {
293	      if (response.status === 402) throw new Error("Not Organic needs more credit or a higher request budget. Open your wallet in Settings.");
294	      if (response.status === 401 || response.status === 403) throw new Error("Not Organic image access is unavailable. Sign in again and check your account permissions.");
295	      throw new Error(`Not Organic image generation failed (${response.status}).`);
296	    }
297	    const data = await response.json() as { data?: Array<{ b64_json?: string; url?: string }> };
298	    const result = data.data?.[0];
299	    if (typeof result?.b64_json === "string" && result.b64_json) {
300	      writeFileSync(outputPath, Buffer.from(result.b64_json, "base64"));
301	    } else if (typeof result?.url === "string") {
302	      const url = await assertSafePublicUrl(result.url);
303	      if (url.protocol !== "https:" || url.username || url.password) throw new Error("Not Organic returned an invalid image URL.");
304	      // Download the provider's HTTPS artifact; credentials are never forwarded.
305	      const response = await fetch(url, { signal: AbortSignal.timeout(60_000), redirect: "error" });
306	      if (!response.ok) throw new Error(`Not Organic image download failed (${response.status}).`);
307	      writeFileSync(outputPath, Buffer.from(await response.arrayBuffer()));
308	    } else {
309	      throw new Error("Not Organic returned no image data.");
310	    }
311	  }
