313	  private async generateOpenAI(prompt: GeneratedPrompt, outputPath: string): Promise<void> {
314	    // https://developers.openai.com/api/docs/guides/image-generation
315	    // Docs confirm 2.5 Sunburst/Flare, not the bare gpt-image-2.5 alias.
316	    // Keep the GPT Image 2 shape for that requested alias pending confirmation.
317	    // GPT Image uses low/medium/high and base64; style is DALL-E-only.
318	    const isGPTImage = this.model.startsWith("gpt-image-");
319	    const response = await fetch("https://api.openai.com/v1/images/generations", {
320	      method: "POST",
321	      headers: {
322	        Authorization: `Bearer ${this.openaiKey}`,
323	        "Content-Type": "application/json",
324	      },
325	      body: JSON.stringify({
326	        model: this.model,
327	        prompt: prompt.prompt,
328	        size: prompt.parameters?.size || this.size,
329	        quality: isGPTImage && this.quality === "standard" ? "medium" : this.quality,
330	        ...(isGPTImage ? {} : { style: this.style }),
331	        n: 1,
332	      }),
333	    });
334	
335	    if (!response.ok) {
336	      const body = await response.text().catch(() => "");
337	      throw new Error(`OpenAI image API error ${response.status}: ${body || response.statusText}`);
338	    }
339	
340	    const data = await response.json();
341	    const result = data.data?.[0];
342	    if (!result) throw new Error("OpenAI returned no image data.");
343	
344	    if (result.b64_json) {
345	      writeFileSync(outputPath, Buffer.from(result.b64_json, "base64"));
346	    } else if (result.url) {
347	      await this.downloadToFile(result.url, outputPath);
348	    } else {
349	      throw new Error("OpenAI returned neither b64_json nor url.");
350	    }
351	  }
