365	  private async generateImagen(prompt: GeneratedPrompt, outputPath: string): Promise<void> {
366	    const url = `https://generativelanguage.googleapis.com/v1beta/models/${this.model}:predict?key=${this.googleKey}`;
367	
368	    const aspectRatio = prompt.parameters?.aspectRatio ?? "1:1";
369	    const response = await fetch(url, {
370	      method: "POST",
371	      headers: { "Content-Type": "application/json" },
372	      body: JSON.stringify({
373	        instances: [{ prompt: prompt.prompt }],
374	        parameters: { sampleCount: 1, aspectRatio },
375	      }),
376	    });
377	
378	    if (!response.ok) {
379	      const body = await response.text().catch(() => "");
380	      throw new Error(`Imagen API error ${response.status}: ${body || response.statusText}`);
381	    }
382	
383	    const data = await response.json();
384	    const prediction = data.predictions?.[0];
385	    if (!prediction?.bytesBase64Encoded) {
386	      throw new Error("Imagen returned no image data.");
387	    }
388	    writeFileSync(outputPath, Buffer.from(prediction.bytesBase64Encoded, "base64"));
