391	  private async generateGeminiFlash(prompt: GeneratedPrompt, outputPath: string): Promise<void> {
392	    const url = `https://generativelanguage.googleapis.com/v1beta/models/${this.model}:generateContent?key=${this.googleKey}`;
393	
394	    const response = await fetch(url, {
395	      method: "POST",
396	      headers: { "Content-Type": "application/json" },
397	      body: JSON.stringify({
398	        contents: [{ parts: [{ text: prompt.prompt }] }],
399	        generationConfig: { responseModalities: ["IMAGE", "TEXT"] },
400	      }),
401	    });
402	
403	    if (!response.ok) {
404	      const body = await response.text().catch(() => "");
405	      throw new Error(`Gemini Flash image API error ${response.status}: ${body || response.statusText}`);
406	    }
407	
408	    const data = await response.json();
409	    const parts: Array<{ inlineData?: { mimeType: string; data: string }; text?: string }> =
410	      data.candidates?.[0]?.content?.parts ?? [];
411	    const imagePart = parts.find((p) => p.inlineData?.mimeType?.startsWith("image/"));
412	    if (!imagePart?.inlineData) {
413	      throw new Error("Gemini Flash returned no image in response.");
414	    }
415	    writeFileSync(outputPath, Buffer.from(imagePart.inlineData.data, "base64"));
416	  }
