427	export class VideoGenerator {
428	  private apiKey: string | undefined;
429	  private outputDir: string;
430	  private provider: NonNullable<GenerationConfig["videoProvider"]>;
431	  private model: string;
432	  private config: GenerationConfig;
433	
434	  constructor(config: GenerationConfig) {
435	    this.config = config;
436	    this.provider = config.videoProvider ?? "seedance";
437	    this.model = config.videoModel ?? { seedance: "seedance-1-0-pro-250528", fal: "fal-ai/bytedance/seedance/v1/pro/text-to-video" }[this.provider as string] ?? "veo-3";
438	    this.apiKey = config.videoApiKey || (this.provider === "seedance" ? process.env.ARK_API_KEY : this.provider === "fal" ? config.falApiKey : config.googleApiKey || process.env.GOOGLE_API_KEY);
439	    this.outputDir = `${config.outputDir}/videos`;
440	    mkdirSync(this.outputDir, { recursive: true });
441	  }
