443	  async generate(persona: Persona, asset: AssetType, prompt: GeneratedPrompt): Promise<GeneratedAsset> {
444	    if (this.provider !== "seedance" && this.provider !== "veo" && this.provider !== "fal") {
445	      throw new Error(`Video provider ${this.provider} is not implemented. Choose seedance, veo or fal.`);
446	    }
447	    if (!this.apiKey) {
448	      throw new Error({ seedance: "Seedance needs ARK_API_KEY", fal: "fal needs FAL_KEY" }[this.provider as string] ?? "Google API key required for video generation. Set GOOGLE_API_KEY.");
449	    }
450	
451	    const startTime = Date.now();
452	    const id = `${persona.id}-${asset.purpose}-${stamp()}`;
453	    let sourceUrl: string | undefined;
454	
455	    const videoResult = this.provider === "seedance"
456	      ? await this.callSeedanceAPI(persona, asset, prompt, `${this.outputDir}/${id}.mp4`)
457	      : this.provider === "fal"
458	        ? await this.callFal(persona, asset, prompt, `${this.outputDir}/${id}.mp4`).then((r) => { sourceUrl = r.sourceUrl; return r.outputPath; })
459	        : await this.callVeoAPI(prompt);
460	
461	    return {
462	      id,
463	      type: "video",
464	      content: videoResult,
465	      prompt: prompt.prompt,
466	      metadata: {
467	        service: { seedance: "byteplus", fal: "fal" }[this.provider as string] ?? "google",
468	        model: this.model,
469	        personaId: persona.id,
470	        assetPurpose: asset.purpose,
471	        generationTime: Date.now() - startTime,
472	        ...(sourceUrl ? { sourceUrl } : {}),
473	      },
474	    };
475	  }
