477	  /**
478	   * Seedance or Kling through fal's queue. Both take a text prompt, a whole-second
479	   * duration and an aspect ratio; Seedance also takes a resolution.
480	   * https://fal.ai/models/fal-ai/bytedance/seedance/v1/pro/text-to-video/api
481	   */
482	  private async callFal(persona: Persona, asset: AssetType, prompt: GeneratedPrompt, outputPath: string): Promise<{ outputPath: string; sourceUrl: string }> {
483	    const duration = Number(this.config.videoDuration ?? prompt.parameters?.duration ?? 5);
484	    const ratio = String(asset.constraints?.aspectRatio ?? this.config.videoRatio ?? prompt.parameters?.aspectRatio ?? "16:9");
485	    const kling = this.model.includes("kling");
486	    if (kling ? ![5, 10].includes(duration) : !Number.isInteger(duration) || duration < 2 || duration > 12) {
487	      throw new Error(kling ? "Kling on fal renders 5 or 10 seconds." : "Seedance duration must be an integer between 2 and 12 seconds.");
488	    }
489	    const result = await falRun<{ video?: { url?: string } }>(this.model, {
490	      prompt: `${prompt.prompt}\nMotion: ${motionPhrase(persona)}. Seamless ambient loop; no text.`,
491	      duration: String(duration),
492	      aspect_ratio: ratio,
493	      ...(kling ? {} : { resolution: String(this.config.videoResolution ?? "1080p"), enable_safety_checker: true }),
494	    }, { key: this.apiKey, timeoutMs: this.config.videoTimeoutMs ?? 15 * 60_000, pollIntervalMs: this.config.videoPollIntervalMs ?? 5_000 });
495	    if (!result.video?.url) throw new Error("fal returned no video.");
496	    return { outputPath, sourceUrl: await falDownload(result.video.url, outputPath) };
497	  }
498	
499	  private async callSeedanceAPI(persona: Persona, asset: AssetType, prompt: GeneratedPrompt, outputPath: string): Promise<string> {
500	    // Official create + retrieve contracts (Bearer ARK_API_KEY; id/status/content.video_url):
501	    // https://docs.byteplus.com/en/docs/modelark/create-video-generation-task-api
502	    // https://docs.byteplus.com/en/docs/modelark/get-video-generation-task-api
503	    // Model ID: https://docs.byteplus.com/en/docs/modelark/recommended-models-seedance-1-0-pro
504	    // fal also hosts Seedance: https://fal.ai/models/bytedance/seedance-2.0/text-to-video/api
505	    // This adapter uses BytePlus directly; it does not use the fal queue protocol.
506	    const base = (this.config.videoBaseUrl ?? "https://ark.ap-southeast.bytepluses.com/api/v3").replace(/\/$/, "");
507	    const endpoint = `${base}/contents/generations/tasks`;
508	    const timeoutMs = this.config.videoTimeoutMs ?? 10 * 60_000;
509	    const intervalMs = this.config.videoPollIntervalMs ?? 5_000;
510	    if (!Number.isFinite(timeoutMs) || timeoutMs <= 0 || !Number.isFinite(intervalMs) || intervalMs < 0) {
511	      throw new Error("Seedance polling requires a positive timeout and nonnegative interval.");
512	    }
513	    const signal = AbortSignal.timeout(timeoutMs);
514	    const headers = { Authorization: `Bearer ${this.apiKey}`, "Content-Type": "application/json" };
515	    const motion = motionPhrase(persona);
516	    const duration = this.config.videoDuration ?? prompt.parameters?.duration ?? 5;
517	    const ratio = asset.constraints?.aspectRatio ?? this.config.videoRatio ?? prompt.parameters?.aspectRatio ?? "16:9";
518	    const resolution = this.config.videoResolution ?? prompt.parameters?.quality ?? "1080p";
519	    // 1.0 Pro accepts whole seconds 2–12 and the listed ratios. Do not silently
520	    // rewrite explicit parameters for other configured models/endpoints.
521	    if (this.model.startsWith("seedance-1-0-") && (!Number.isInteger(duration) || Number(duration) < 2 || Number(duration) > 12)) {
522	      throw new Error("Seedance 1.0 duration must be an integer between 2 and 12 seconds.");
523	    }
524	    if (!["16:9", "4:3", "1:1", "3:4", "9:16", "21:9", "adaptive"].includes(String(ratio))) {
525	      throw new Error(`Unsupported Seedance ratio: ${ratio}`);
526	    }
527	    const created = await fetch(endpoint, {
528	      method: "POST", headers, signal,
529	      body: JSON.stringify({ model: this.model, content: [{ type: "text", text: `${prompt.prompt}\nMotion: ${motion}. Seamless ambient loop; no text.` }], duration, ratio, resolution }),
530	    });
531	    if (!created.ok) throw new Error(`Seedance create task API error ${created.status}`);
532	    const task = await created.json();
533	    if (typeof task.id !== "string" || !task.id) throw new Error("Seedance returned no task ID.");
534	
535	    while (!signal.aborted) {
536	      const response = await fetch(`${endpoint}/${encodeURIComponent(task.id)}`, { headers, signal });
537	      if (!response.ok) throw new Error(`Seedance poll task API error ${response.status}`);
538	      const result = await response.json();
539	      if (result.status === "succeeded") {
540	        if (typeof result.content?.video_url !== "string" || !result.content.video_url) {
541	          throw new Error("Seedance succeeded without a video URL.");
542	        }
543	        // Signed download URL; never forward the ARK key to storage hosts.
544	        const download = await fetch(result.content.video_url, { signal });
545	        if (!download.ok) throw new Error(`Seedance video download failed: ${download.status}`);
546	        writeFileSync(outputPath, Buffer.from(await download.arrayBuffer()));
547	        return outputPath;
548	      }
549	      if (["failed", "cancelled", "expired"].includes(result.status)) {
550	        throw new Error(`Seedance task ${result.status}${result.error?.code ? ` (${result.error.code})` : ""}`);
551	      }
552	      if (result.status !== "queued" && result.status !== "running") {
553	        throw new Error("Seedance returned an unknown task status.");
554	      }
555	      await new Promise<void>((resolve, reject) => {
556	        const done = () => { signal.removeEventListener("abort", abort); resolve(); };
557	        const timer = setTimeout(done, intervalMs);
558	        const abort = () => { clearTimeout(timer); reject(new Error("Seedance task polling timed out.")); };
559	        signal.addEventListener("abort", abort, { once: true });
560	        if (signal.aborted) abort();
561	      });
562	    }
563	    throw new Error("Seedance task polling timed out.");
564	  }
