593	let lastStamp = 0;
594	/**
595	 * Millisecond timestamp for asset ids, unique within this process. QD runs a
596	 * batch of candidates concurrently; two started in the same millisecond must
597	 * not write to the same file.
598	 */
599	function stamp(): number {
600	  const now = Date.now();
601	  lastStamp = now > lastStamp ? now : lastStamp + 1;
602	  return lastStamp;
603	}
