605	function motionPhrase(persona: Persona): string {
606	  return {
607	    smooth: "Slow, smooth movement with gentle continuous pacing",
608	    liquid: "Flowing organic movement, fluid morphs and soft transitions",
609	    snappy: "Crisp, brief motion accents with readable pauses",
610	    mechanical: "Precise, rhythmic mechanical movement",
611	  }[persona.aesthetic.motionStyle];
612	}
