614	/** Trim a prompt to a model's limit at the last whole line that fits. */
615	export function clipPrompt(prompt: string, max: number): string {
616	  const text = prompt.trim();
617	  if (text.length <= max) return text;
618	  const cut = text.slice(0, max);
619	  const line = cut.lastIndexOf("\n");
620	  return (line > max * 0.6 ? cut.slice(0, line) : cut).trim();
621	}
622	
623	function hexToRgb(hex: string): { r: number; g: number; b: number } | null {
624	  const m = /^#?([0-9a-f]{6})$/i.exec(hex.trim());
625	  if (!m) return null;
626	  const n = parseInt(m[1], 16);
627	  return { r: (n >> 16) & 255, g: (n >> 8) & 255, b: n & 255 };
628	}
