656	  async generateBatch(
657	    persona: Persona,
658	    assets: AssetType[],
659	    prompts: Record<string, GeneratedPrompt>
660	  ): Promise<GeneratedAsset[]> {
661	    const results: GeneratedAsset[] = [];
662	    for (const asset of assets) {
663	      const prompt = prompts[asset.kind];
664	      if (!prompt) {
665	        console.warn(`No prompt for asset type: ${asset.kind}`);
666	        continue;
667	      }
668	      try {
669	        results.push(await this.generate(persona, asset, prompt));
670	      } catch (error) {
671	        console.error(`Failed to generate ${asset.kind} asset:`, error);
672	      }
673	    }
674	    return results;
675	  }
