1	/**
2	 * Prompt Engineering Engine
3	 * 
4	 * Transform persona + asset type into optimized prompts for:
5	 * - SVG generation (QuiverAI)
6	 * - Image generation (DALL-E 3 / ChatGPT Image)
7	 * - Video generation (Veo 3)
8	 */
9	
10	import type { Persona, AestheticProfile } from "../persona/types.js";
11	
12	export interface AssetType {
13	  kind: "svg" | "image" | "video";
14	  purpose: string; // "icon", "illustration", "background", "hero", "component", "animation"
15	  description: string;
16	  constraints?: {
17	    style?: string;
18	    aspectRatio?: string;
19	    size?: string;
20	    colors?: string[];
21	  };
22	}
23	
24	export interface GeneratedPrompt {
25	  prompt: string;
26	  negativePrompt?: string;
27	  parameters: Record<string, unknown>;
28	  systemContext: string;
29	}
30	
31	/**
32	 * Generate prompts optimized for each generation service
33	 */
34	export function generatePrompts(
35	  persona: Persona,
36	  asset: AssetType
37	): Record<string, GeneratedPrompt> {
38	  const aesthetic = persona.aesthetic;
39	
40	  return {
41	    svg: generateSVGPrompt(persona, aesthetic, asset),
42	    image: generateImagePrompt(persona, aesthetic, asset),
43	    video: generateVideoPrompt(persona, aesthetic, asset),
44	  };
45	}
46	
47	function generateSVGPrompt(
48	  persona: Persona,
49	  aesthetic: AestheticProfile,
50	  asset: AssetType
51	): GeneratedPrompt {
52	  const baseStyle = buildStyleDescription(aesthetic);
53	  const influence = selectRandomInfluence(persona.influences);
54	
55	  const prompt = `Create an ${asset.purpose} SVG in the style of ${baseStyle}.
56	
57	Visual concept: ${asset.description}
58	
59	Inspired by ${persona.name}'s world:
60	- Influences: ${influence}
61	- Mood: ${aesthetic.moodKeywords.slice(0, 3).join(", ")}
62	- Visual DNA: ${aesthetic.visualKeywords.slice(0, 4).join(", ")}
63	
64	Requirements:
65	- Clean, scalable vector paths
66	- ${aesthetic.colorTemperature} color palette
67	- ${aesthetic.density === "minimal" ? "Minimal detail, generous negative space" : "Rich detail, layered elements"}
68	- ${aesthetic.edgeStyle === "organic" ? "Flowing, organic curves" : "Sharp, defined edges"}
69	- Style should feel ${aesthetic.textureStyle}
70	- Must work on both light and dark backgrounds
71	- No text unless essential to the concept
