243	/**
244	 * The QD archive's three axes, each as ordered steps a prompt can move along.
245	 * The persona's own position is where a fitting starts; mutation explores its
246	 * neighbours so the archive fills with real alternatives, not one look repeated.
247	 */
248	const TEMPERATURE = ["icy blue and violet", "cool teal and slate", "muted, desaturated", "neutral, balanced", "warm amber and terracotta", "deep ember orange and red"];
249	const DENSITY = ["almost empty, one subject", "sparse, generous negative space", "balanced", "rich, layered", "dense, packed with detail", "maximalist, every surface busy"];
250	const RENDERING = ["literal, photographic", "cinematic, lightly stylised", "illustrative, painterly", "graphic, flat-shaded", "abstract, pattern-led"];
251	
252	/** Where a persona's own aesthetic sits on each axis: the centre of its fitting. */
253	function axisStart(aesthetic: AestheticProfile): [string, string, string] {
254	  const temperature = { cool: 1, muted: 2, neutral: 3, "high-contrast": 3, warm: 4 }[aesthetic.colorTemperature] ?? 3;
255	  const density = { minimal: 1, rich: 3, dense: 4, maximalist: 5 }[aesthetic.density] ?? 3;
256	  const rendering = aesthetic.density === "minimal" ? 2 : 1;
257	  return [TEMPERATURE[temperature], DENSITY[density], RENDERING[rendering]];
258	}
259	
260	/** Move one axis line up or down its scale by one or two steps, bouncing off either end. */
261	function stepAxis(prompt: string, line: RegExp, steps: string[], suffix: string): string {
262	  const match = line.exec(prompt);
263	  if (!match) return prompt;
264	  const found = steps.indexOf(match[1]);
265	  const from = found >= 0 ? found : Math.floor(steps.length / 2);
266	  const size = Math.random() < 0.3 ? 2 : 1;
267	  let to = from + (Math.random() < 0.5 ? -size : size);
268	  if (to < 0 || to >= steps.length) to = from + (to < 0 ? size : -size);
269	  return prompt.replace(line, `- ${steps[to]} ${suffix}`);
270	}
