272	export function mutatePrompt(
273	  basePrompt: string,
274	  persona: Persona,
275	  mutationRate: number
276	): string {
277	  let mutated = basePrompt;
278	
279	  // Explore the archive's feature space: colour temperature, density, abstraction.
280	  const axes: Array<[RegExp, string[], string]> = [
281	    [/^- (.+) color temperature$/m, TEMPERATURE, "color temperature"],
282	    [/^- (.+) visual density$/m, DENSITY, "visual density"],
283	    [/^- (.+) rendering$/m, RENDERING, "rendering"],
284	  ];
285	  const before = mutated;
286	  for (const [line, steps, suffix] of axes) {
287	    if (Math.random() < mutationRate) mutated = stepAxis(mutated, line, steps, suffix);
288	  }
289	  // Every child moves somewhere in feature space, or the archive cannot grow.
290	  if (mutated === before) {
291	    const [line, steps, suffix] = axes[Math.floor(Math.random() * axes.length)];
292	    mutated = stepAxis(mutated, line, steps, suffix);
293	  }
294	
295	  // Swap visual keywords
296	  if (Math.random() < mutationRate) {
297	    const keywords = persona.aesthetic.visualKeywords;
298	    const swap1 = keywords[Math.floor(Math.random() * keywords.length)];
299	    const swap2 = keywords[Math.floor(Math.random() * keywords.length)];
300	    mutated = mutated.replace(swap1, swap2);
301	  }
302	
303	  // Alter mood keywords
304	  if (Math.random() < mutationRate) {
305	    const moods = persona.aesthetic.moodKeywords;
306	    const newMood = moods[Math.floor(Math.random() * moods.length)];
307	    mutated = mutated.replace(
308	      /Emotional tone: .+/,
309	      `Emotional tone: ${newMood}`
310	    );
311	  }
312	
313	  // Swap influence
314	  if (Math.random() < mutationRate) {
315	    const newInfluence = selectRandomInfluence(persona.influences);
316	    mutated = mutated
317	      .replace(/Inspired by .+\n/, `Inspired by ${newInfluence}\n`)
318	      .replace(/- Visual influences: .+/, `- Visual influences: ${newInfluence}`);
319	  }
320	
321	  return mutated;
322	}
