131	function tally(items: string[]): Array<[string, number]> {
132	  const counts = new Map<string, number>();
133	  for (const t of items) counts.set(t, (counts.get(t) ?? 0) + 1);
134	  return [...counts.entries()].sort((a, b) => b[1] - a[1]);
135	}
136	
137	function averageFeatures(entries: FeedbackEntry[]): number[] | null {
138	  const withFeatures = entries.filter((e) => e.features && e.features.length >= 3);
139	  if (withFeatures.length === 0) return null;
140	  const dim = Math.min(...withFeatures.map((e) => e.features!.length));
141	  const avg = new Array(dim).fill(0);
142	  for (const e of withFeatures) for (let i = 0; i < dim; i++) avg[i] += e.features![i];
143	  return avg.map((v) => v / withFeatures.length);
144	}
145	
146	function sample<T>(arr: T[], n: number): T[] {
147	  if (arr.length <= n) return arr;
148	  const out: T[] = [];
149	  const taken = new Set<number>();
150	  while (out.length < n) {
151	    const i = Math.floor(Math.random() * arr.length);
152	    if (taken.has(i)) continue;
153	    taken.add(i);
154	    out.push(arr[i]);
155	  }
156	  return out;
157	}
