163	  total: number;
164	  positive: number;
165	  negative: number;
166	  topUpTags: Array<{ tag: string; count: number }>;
167	  topDownTags: Array<{ tag: string; count: number }>;
168	  recent: FeedbackEntry[];
169	} {
170	  const entries = loadFeedback(personaId);
171	  const ups = entries.filter((e) => e.score > 0);
172	  const downs = entries.filter((e) => e.score < 0);
173	  return {
174	    total: entries.length,
175	    positive: ups.length,
176	    negative: downs.length,
177	    topUpTags: tally(ups.flatMap((e) => e.tags ?? [])).slice(0, 6).map(([tag, count]) => ({ tag, count })),
178	    topDownTags: tally(downs.flatMap((e) => e.tags ?? [])).slice(0, 6).map(([tag, count]) => ({ tag, count })),
179	    recent: entries.slice(-15).reverse(),
