.motion-enter { animation: baste-enter 200ms cubic-bezier(0.05, 0.7, 0.1, 1) 1 normal both; }

/* Leave: dismissals and content making way. */
.motion-exit { animation: baste-exit 100ms cubic-bezier(0.3, 0, 0.8, 0.15) 1 normal both; }

/* Answer the pointer: lift, swell or slide toward the cursor. */
.motion-hover { transition-property: transform; transition-duration: 100ms; transition-timing-function: cubic-bezier(0.2, 0, 0, 1); }
.motion-hover:hover { transform: translateY(-2px); }

/* Confirm a press: the control gives under the finger. */
.motion-press { transition-property: transform; transition-duration: 100ms; transition-timing-function: cubic-bezier(0.2, 0, 0, 1); }
.motion-press:active { transform: scale(0.96); }

/* Draw the eye once: a new badge, a saved state, a result. */
.motion-emphasis { animation: baste-emphasis 400ms cubic-bezier(0.2, 0, 0, 1) 1 normal both; }

/* Flicker: a sign catching power, then a long readable hold. */
.motion-ambient { animation: baste-ambient 4000ms steps(1, end) infinite normal both; }

/* Sequence: the children of .motion-stagger enter one after another. */
.motion-stagger > * { animation: baste-enter 200ms cubic-bezier(0.05, 0.7, 0.1, 1) 1 normal both; }
.motion-stagger > :nth-child(2) { animation-delay: calc(1 * var(--motion-stagger)); }
.motion-stagger > :nth-child(3) { animation-delay: calc(2 * var(--motion-stagger)); }
.motion-stagger > :nth-child(4) { animation-delay: calc(3 * var(--motion-stagger)); }
.motion-stagger > :nth-child(5) { animation-delay: calc(4 * var(--motion-stagger)); }
.motion-stagger > :nth-child(6) { animation-delay: calc(5 * var(--motion-stagger)); }
.motion-stagger > :nth-child(7) { animation-delay: calc(6 * var(--motion-stagger)); }
.motion-stagger > :nth-child(8) { animation-delay: calc(7 * var(--motion-stagger)); }
.motion-stagger > :nth-child(9) { animation-delay: calc(8 * var(--motion-stagger)); }
.motion-stagger > :nth-child(10) { animation-delay: calc(9 * var(--motion-stagger)); }
.motion-stagger > :nth-child(11) { animation-delay: calc(10 * var(--motion-stagger)); }
.motion-stagger > :nth-child(12) { animation-delay: calc(11 * var(--motion-stagger)); }

@media (prefers-reduced-motion: reduce) {
  @keyframes baste-enter-reduced {
    0% { opacity: 0; }
    100% { opacity: 1; }
  }
  @keyframes baste-exit-reduced {
    0% { opacity: 1; }
    100% { opacity: 0; }
  }
  .motion-enter, .motion-stagger > * { animation-name: baste-enter-reduced; animation-delay: 0s; }
  .motion-exit { animation-name: baste-exit-reduced; }
  .motion-hover, .motion-hover:hover, .motion-press, .motion-press:active { transform: none; transition: none; }
  .motion-emphasis, .motion-ambient { animation: none; }
}

