/**
 * Scan images from a directory and add as cultural references.
 */
scanCulturalImages(
  personaId: string,
  imagePaths: string[],
  rationale: string
): CulturalReference[] {
  const refs: CulturalReference[] = [];
  for (const path of imagePaths) {
    const ref = this.addCulturalReference(personaId, {
      type: "image",
      value: `Image: ${path}`,
      designRationale: rationale,
      source: path,
    });
    refs.push(ref);
  }
  return refs;
}

