export async function videoFrames(path, longSide = 512) {
    if (!ffmpegAvailable())
        return [];
    try {
        // Local files only, read through ffmpeg's file protocol: a URL or a
        // "concat:"-style name must never make ffmpeg fetch or splice something else.
        if (!statSync(path).isFile())
            return [];
        const input = `file:${path}`;
        const { stdout } = await run("ffprobe", ["-v", "error", "-select_streams", "v:0", "-show_entries", "stream=width,height:format=duration", "-of", "json", input], { timeout: 10_000 });
        const probe = JSON.parse(stdout);
        const width = probe.streams?.[0]?.width ?? 0;
        const height = probe.streams?.[0]?.height ?? 0;
        const duration = Number(probe.format?.duration);
        if (!(width > 0 && height > 0 && duration > 0))
            return [];
        const fit = fitStill(width, height, longSide);
        const frames = await Promise.all(FRAME_POSITIONS.map(async (position) => {
            const seconds = Math.max(0, Math.min(duration * position, duration - 0.1));
            const { stdout: jpeg } = await run("ffmpeg", ["-v", "error", "-ss", seconds.toFixed(3), "-i", input, "-frames:v", "1", "-vf", fitFilter(fit), ...JPEG_OUT, "pipe:1"], { encoding: "buffer", maxBuffer: 16 * 1024 * 1024, timeout: 20_000 });
            return jpeg.length ? { seconds: Math.round(seconds * 100) / 100, still: { data: new Uint8Array(jpeg), format: "jpeg", width: fit.canvasWidth, height: fit.canvasHeight } } : undefined;
        }));
        return frames.every(Boolean) ? frames : [];
    }
    catch {
        return [];
    }
}
