2	 * Stills a vision judge can read: PNG files inside TypeSafe's image limits.
3	 * https://docs.typesafe.ai/images.md accepts PNG or JPEG stills 280–1568 px a
4	 * side and never resizes, so everything is fitted here first. PNG and JPEG are
5	 * redrawn by resvg (already a dependency); WebP, GIF and video frames need
6	 * ffmpeg, and are skipped without it.
7	 */
8	import { execFile, spawnSync } from "node:child_process";
9	import { readFileSync, statSync } from "node:fs";
10	import { promisify } from "node:util";
11	import { Resvg } from "@resvg/resvg-js";
12	import { parseImageDimensions } from "./img-dims.js";
13	
14	const run = promisify(execFile);
15	
16	export interface Still {
17	  data: Uint8Array;
18	  format: "png" | "jpeg";
19	  width: number;
20	  height: number;
21	}
22	
23	export const STILL_MIN_SIDE = 280;
24	export const STILL_MAX_SIDE = 1568;
25	/** Neutral ground behind transparent pixels and letterboxing. */
26	const GROUND = "#e7e5e0";
27	
28	/**
29	 * Pixel size for an image drawn with its long side at most `longSide`, then
30	 * enlarged until both sides reach the minimum. A canvas that is still too
31	 * narrow (a very wide banner) is padded rather than distorted.
32	 */
33	export function fitStill(width: number, height: number, longSide: number): { width: number; height: number; canvasWidth: number; canvasHeight: number } {
34	  if (!(width > 0 && height > 0)) throw new Error("Image has no size.");
35	  let scale = Math.min(1, Math.min(longSide, STILL_MAX_SIDE) / Math.max(width, height));
36	  if (Math.min(width, height) * scale < STILL_MIN_SIDE) scale = STILL_MIN_SIDE / Math.min(width, height);
37	  if (Math.max(width, height) * scale > STILL_MAX_SIDE) scale = STILL_MAX_SIDE / Math.max(width, height);
38	  const w = Math.max(1, Math.round(width * scale));
39	  const h = Math.max(1, Math.round(height * scale));
40	  const side = (n: number) => Math.min(STILL_MAX_SIDE, Math.max(STILL_MIN_SIDE, n));
41	  return { width: w, height: h, canvasWidth: side(w), canvasHeight: side(h) };
42	}
43	
44	function render(svg: string): Still {
45	  const image = new Resvg(svg, { fitTo: { mode: "original" } }).render();
46	  return { data: image.asPng(), format: "png", width: image.width, height: image.height };
47	}
48	
49	/** One image centred on a neutral canvas, drawn at its fitted size. */
50	function redraw(href: string, width: number, height: number, longSide: number): Still {
51	  const fit = fitStill(width, height, longSide);
52	  const x = (fit.canvasWidth - fit.width) / 2;
53	  const y = (fit.canvasHeight - fit.height) / 2;
54	  return render(`<svg xmlns="http://www.w3.org/2000/svg" width="${fit.canvasWidth}" height="${fit.canvasHeight}">`
55	    + `<rect width="100%" height="100%" fill="${GROUND}"/>`
56	    + `<image x="${x}" y="${y}" width="${fit.width}" height="${fit.height}" preserveAspectRatio="none" href="${href}"/></svg>`);
