64	  const head = buffer.subarray(0, 512).toString("utf8").trimStart().toLowerCase();
65	  return head.startsWith("<svg") || (head.startsWith("<?xml") && head.includes("<svg")) || (head.startsWith("<!--") && head.includes("<svg"));
66	}
