          .describe("Existing persona ID to extend from"),
        cultureSubcultures: z
          .array(z.string())
          .optional()
          .describe("Subcultures, e.g. ['solarpunk', 'mycology']"),
        cultureValues: z
          .array(z.string())
          .optional()
          .describe("Values, e.g. ['sustainability', 'open-source']"),
        films: z.array(z.string()).optional(),
        anime: z.array(z.string()).optional(),
        musicGenres: z.array(z.string()).optional(),
        visualArtists: z.array(z.string()).optional(),
          return {
            content: [
              { type: "text", text: `Base persona not found: ${args.baseId}` },
            ],
            isError: true,
          };
        }
        persona = extendPersona(base, draft);
      } else {
        persona = buildPersona(draft);
      }

      // Overlay optional fields
      if (args.cultureSubcultures)
        persona.culture.subcultures = args.cultureSubcultures;
      if (args.cultureValues) persona.culture.values = args.cultureValues;
      if (args.films) persona.influences.films = args.films;
      if (args.anime) persona.influences.anime = args.anime;
      if (args.musicGenres)
        persona.influences.music.genres = args.musicGenres;
      if (args.visualArtists)
        persona.influences.visualArtists = args.visualArtists;
      if (args.spaces) persona.influences.spaces = args.spaces;
      if (args.obsessions) persona.influences.obsessions = args.obsessions;
      if (args.colorTemperature)
        persona.aesthetic.colorTemperature = args.colorTemperature;
      if (args.density) persona.aesthetic.density = args.density;
      if (args.edgeStyle) persona.aesthetic.edgeStyle = args.edgeStyle;
      if (args.motionStyle) persona.aesthetic.motionStyle = args.motionStyle;
      if (args.typographyStyle)
        persona.aesthetic.typographyStyle = args.typographyStyle;
      if (args.textureStyle) persona.aesthetic.textureStyle = args.textureStyle;
      if (args.iconStyle) persona.aesthetic.iconStyle = args.iconStyle;
      if (args.layoutStyle) persona.aesthetic.layoutStyle = args.layoutStyle;
      if (args.visualKeywords)
        persona.aesthetic.visualKeywords = args.visualKeywords;
      if (args.moodKeywords)
        persona.aesthetic.moodKeywords = args.moodKeywords;

      savePersona(persona);
      return {
        content: [
          { type: "text", text: `Created persona: ${args.id} (${args.name})` },
        ],
      };
    }
  );

1	/**
2	 * Baste Core Orchestrator
3	 * 
4	 * Main engine that coordinates:
5	 * 1. Persona loading
6	 * 2. Prompt generation
7	 * 3. Quality-Diversity evolution
8	 * 4. Asset generation (SVG, Image, Video)
9	 * 5. LLM-as-a-judge evaluation
10	 * 6. Archive management and output
11	 */
12	
13	import type { Persona } from "./persona/types.js";
14	import { resolveEvaluatorProvider, type EvaluatorConfig } from "./config/baste-config.js";
15	import type { AssetType, GeneratedPrompt } from "./generation/prompts.js";
16	import { generatePrompts, mutatePrompt } from "./generation/prompts.js";
17	import {
18	  runQD,
19	  defaultAssetFeatures,
20	  getDiverseSamples,
21	  type QDConfig,
22	  type QDSolution,
23	  type QDArchive,
24	} from "./generation/qd.js";
25	import {
26	  evaluateBatch,
27	  createScorer,
28	  type EvaluationResult,
29	} from "./evaluation/judge.js";
30	import {
31	  AssetGenerator,
32	  type GenerationConfig,
33	  type GeneratedAsset,
34	} from "./assets/generators.js";
35	import { judgeWithFal, svgPreview } from "./evaluation/fal-judge.js";
36	import { loadJudgeContext, type JudgeContext } from "./evaluation/visual-context.js";
37	import { ffmpegAvailable } from "./shared/stills.js";
38	
39	export interface BasteConfig {
40	  // Generation services config
41	  generation: GenerationConfig;
42	
43	  // QD parameters
44	  qd: QDConfig;
45	
46	  // Number of final assets to produce per type
47	  outputCount: number;
48	
49	  // LLM evaluator config
50	  evaluator: EvaluatorConfig;
51	}
52	
53	/** One image the QD search generated and judged, kept or not. */
54	export interface QDCandidate {
55	  generation: number;
56	  path: string;
57	  sourceUrl?: string;
58	  quality: number;
59	  features: number[];
60	  criteria: EvaluationResult["criteria"];
61	  feedback: string;
62	  /** Archive cell it landed in, when it beat that cell's previous holder. */
63	  cell?: string;
64	}
65	
66	export interface AssetSuite {
67	  persona: Persona;
68	  assets: {
69	    svgs: GeneratedAsset[];
70	    images: GeneratedAsset[];
71	    videos: GeneratedAsset[];
72	  };
73	  archive: QDArchive<string>; // genome = prompt string
74	  evaluations: EvaluationResult[];
75	  /** Every QD candidate in generation order, with where it landed. */
76	  candidates: QDCandidate[];
77	  /** Judge scores for each final asset, by asset id. */
78	  finalScores: Record<string, EvaluationResult>;
79	  metadata: {
80	    generationDuration: number;
81	    totalIterations: number;
82	    coverage: number;
83	  };
84	}
85	
86	/**
87	 * Generate a complete asset suite for a persona
88	 */
89	/** Live progress for callers that show a run as it happens, such as the Studio. */
90	export interface GenerationHooks {
91	  log?: (line: string) => void;
92	  /** Each QD candidate as soon as it has been generated and judged. */
93	  candidate?: (candidate: QDCandidate) => void;
94	}
95	
96	export async function generateAssetSuite(
97	  persona: Persona,
98	  assetTypes: AssetType[],
99	  config: BasteConfig,
100	  hooks: GenerationHooks = {},
101	): Promise<AssetSuite> {
102	  const log = hooks.log ?? console.log;
103	  const startTime = Date.now();
104	  const generator = new AssetGenerator(config.generation);
105	  const evaluations: EvaluationResult[] = [];
106	  const candidates: QDCandidate[] = [];
107	  const finalScores: Record<string, EvaluationResult> = {};
108	  const evaluatorProvider = resolveEvaluatorProvider(config.evaluator);
109	  // Surface missing credentials to the GUI before generating paid assets.
110	  if (assetTypes.some(a => a.kind === "video") && (config.generation.videoProvider ?? "seedance") === "seedance"
111	      && !config.generation.videoApiKey && !process.env.ARK_API_KEY) {
112	    throw new Error("Seedance needs ARK_API_KEY");
113	  }
114	  const needsFal = evaluatorProvider === "fal"
115	    || (config.generation.imageProvider === "fal" && assetTypes.some(a => a.kind === "image"))
116	    || (config.generation.svgProvider === "fal" && assetTypes.some(a => a.kind === "svg"))
117	    || (config.generation.videoProvider === "fal" && assetTypes.some(a => a.kind === "video"));
118	  if (needsFal && !config.generation.falApiKey && !process.env.FAL_KEY) {
119	    throw new Error("fal needs FAL_KEY");
120	  }
121	
122	  // Jev looks at pixels: load the persona's reference images and rated examples once.
123	  let judgeContext: JudgeContext | undefined;
124	  if (evaluatorProvider === "typesafe" && config.evaluator.vision !== false && (config.evaluator.apiKey || process.env.TYPESAFE_API_KEY)) {
125	    judgeContext = await loadJudgeContext(persona, config.generation.outputDir);
126	    const { references, examples } = judgeContext;
127	    const rated = examples.image.liked.length + examples.image.disliked.length + examples.svg.liked.length + examples.svg.disliked.length;
128	    log(`   Jev looks at each asset${references.length ? `, beside ${references.length} reference image${references.length === 1 ? "" : "s"}` : ""}${rated ? ` and ${rated} rated example${rated === 1 ? "" : "s"}` : ""}`);
129	    if (assetTypes.some((a) => a.kind === "video") && !ffmpegAvailable()) log("   Install ffmpeg to let Jev read video frames; loops are judged on their prompt");
130	  }
131	
132	  log(`\n🎨 Baste: Generating assets for "${persona.name}"`);
133	  log(`   Persona: ${persona.summary}`);
134	  log(`   Asset types: ${assetTypes.map((a) => a.kind).join(", ")}`);
135	
136	  // Generate prompts for each asset type
137	  const promptsByAsset = new Map<AssetType, Record<string, GeneratedPrompt>>();
138	  for (const asset of assetTypes) {
139	    promptsByAsset.set(asset, generatePrompts(persona, asset));
140	  }
141	
142	  // Run QD evolution for image assets (most impactful for UI)
143	  const imageAssets = assetTypes.filter((a) => a.kind === "image");
144	  let archive: QDArchive<string> = createArchive(config.qd);
145	
146	  if (imageAssets.length > 0) {
147	    log("\n🧬 Starting QD evolution for images...");
148	
149	    const imageAsset = imageAssets[0];
150	    const prompts = promptsByAsset.get(imageAsset)!;
151	
152	    archive = await runQD<string>(
153	      { ...config.qd, log },
154	      // Seed generation
155	      async () => ({
156	        genome: prompts.image.prompt,
157	        quality: 0,
158	        features: [0, 0, 0],
159	        generation: 0,
160	      }),
161	      // Mutation
162	      async (parent, rate) => ({
163	        genome: mutatePrompt(parent.genome, persona, rate),
164	        quality: 0,
165	        features: [0, 0, 0],
166	        generation: 0,
167	      }),
168	      // Evaluation
169	      async (genome, { generation }) => {
170	        // Generate the asset
171	        const asset = await generator.generate(persona, imageAsset, {
172	          ...prompts.image,
173	          prompt: genome,
174	        });
175	
176	        // Evaluate with LLM judge
177	        const evalResults = await evaluateBatch(
178	          persona,
179	          [
180	            {
181	              type: "image",
182	              prompt: genome,
183	              content: asset.content,
184	              purpose: imageAsset.purpose,
185	              metadata: asset.metadata,
186	              suite: assetTypes.map(a => ({ type: a.kind, purpose: a.purpose, prompt: promptsByAsset.get(a)![a.kind].prompt })),
187	              judgeContext,
188	            },
189	          ],
190	          // Evaluation function: a vision model on fal, or OpenAI over the prompt
191	          async (system, user) => {
192	            if (evaluatorProvider === "fal") {
193	              return judgeWithFal(system, user, { model: config.evaluator.model, apiKey: config.evaluator.apiKey, temperature: config.evaluator.temperature, imageUrl: asset.metadata.sourceUrl });
194	            }
195	            const apiKey = config.evaluator.apiKey || process.env.OPENAI_API_KEY;
196	            if (!apiKey) {
197	              console.warn("[baste] No OPENAI_API_KEY set — using rule-based heuristic evaluation (set OPENAI_API_KEY or evaluator.apiKey for LLM judge)");
198	              // Local heuristic: score based on prompt richness and persona keyword overlap.
199	              // Ensures the archive is still useful even without an LLM API key.
200	              const keywords = [...persona.aesthetic.visualKeywords, ...persona.aesthetic.moodKeywords];
201	              const promptWords = genome.toLowerCase().split(/[^a-z]+/);
202	              const overlap = keywords.filter(k => promptWords.includes(k.toLowerCase())).length;
203	              const normOverlap = keywords.length ? Math.min(1, overlap / Math.max(1, keywords.length * 0.3)) : 0.5;
204	              const richness = Math.min(1, promptWords.filter(w => w.length > 3).length / 20);
205	              const baseScore = 0.4 + (normOverlap * 0.35) + (richness * 0.15);
206	              const paScore = Math.min(1, baseScore + 0.05 * Math.random());
207	              const vqScore = Math.min(1, 0.5 + richness * 0.4 + 0.05 * Math.random());
208	              const unScore = Math.min(1, 0.45 + normOverlap * 0.45 + 0.05 * Math.random());
209	              const coScore = Math.min(1, 0.5 + 0.3 * richness + 0.05 * Math.random());
210	              const usScore = Math.min(1, 0.55 + 0.3 * normOverlap + 0.05 * Math.random());
211	              const overall = paScore * 0.3 + vqScore * 0.2 + unScore * 0.2 + coScore * 0.15 + usScore * 0.15;
212	              return JSON.stringify({
213	                overall,
214	                criteria: {
215	                  personaAlignment: +paScore.toFixed(3),
216	                  visualQuality: +vqScore.toFixed(3),
217	                  uniqueness: +unScore.toFixed(3),
218	                  coherence: +coScore.toFixed(3),
219	                  usability: +usScore.toFixed(3),
220	                },
221	                features: [
222	                  +(Math.random() * 2 - 1).toFixed(3),
223	                  +richness.toFixed(3),
224	                  +normOverlap.toFixed(3),
225	                ],
226	                feedback: `Local heuristic evaluation: prompt-keyword overlap=${(normOverlap * 100).toFixed(0)}%, prompt richness=${(richness * 100).toFixed(0)}%. ` +
227	                  (normOverlap > 0.5 ? "Strong persona alignment" : normOverlap > 0.2 ? "Moderate persona alignment, consider more persona keywords" : "Weak persona alignment, refine prompt"),
228	                improvements: [
229	                  "Add API key for LLM judge (OPENAI_API_KEY)",
230	                  normOverlap < 0.5 ? `Inject more ${persona.aesthetic.visualKeywords.slice(0,3).join(", ")} keywords` : "Explore contrasting moods for diversity",
231	                  richness < 0.5 ? "Expand prompt with detail: lighting, materials, composition" : "Experiment with shorter, punchier prompts",
232	                ],
233	                tags: ["heuristic", normOverlap > 0.5 ? "aligned" : "needs-work", richness > 0.5 ? "rich" : "sparse", "local-eval"],
234	              });
235	            }
236	
237	            const response = await fetch("https://api.openai.com/v1/chat/completions", {
238	              method: "POST",
239	              headers: {
240	                Authorization: `Bearer ${apiKey}`,
241	                "Content-Type": "application/json",
242	              },
243	              body: JSON.stringify({
244	                model: config.evaluator.model,
245	                messages: [
246	                  { role: "system", content: system },
247	                  { role: "user", content: user },
248	                ],
249	                temperature: 0.3,
250	              }),
251	            });
252	
253	            const data = await response.json();
254	            return data.choices[0]?.message?.content || "";
255	          },
256	          config.evaluator
257	        );
258	
259	        const result = evalResults[0];
260	        evaluations.push(result);
261	        const scorer = createScorer(config.evaluator.weights);
262	        const quality = scorer(result);
263	        const candidate: QDCandidate = {
264	          generation, path: asset.content, sourceUrl: asset.metadata.sourceUrl, quality,
265	          features: result.features, criteria: result.criteria, feedback: result.feedback,
266	        };
267	        candidates.push(candidate);
268	        hooks.candidate?.(candidate);
269	        log(`   Candidate ${candidates.length} (generation ${generation}) judged ${quality.toFixed(2)}`);
270	
271	        return {
272	          quality,
273	          features: result.features,
274	        };
275	      }
276	    );
277	    // Record which candidates hold a cell in the final archive.
278	    for (const [cell, solution] of archive.cells) {
279	      const held = candidates.find((c) => c.quality === solution.quality && c.features.every((f, i) => f === solution.features[i]));
280	      if (held) held.cell = cell;
281	    }
282	  }
283	
284	  // Generate final diverse assets from archive
285	  log("\n🎯 Generating final assets...");
286	  const diversePrompts = imageAssets.length > 0 ? getDiverseSamples(archive, config.outputCount)
287	    : [{ genome: "", quality: 0, features: [0, 0, 0], generation: 0 }];
288	
289	  const finalAssets: GeneratedAsset[] = [];
290	
291	  for (const solution of diversePrompts) {
292	    for (const assetType of assetTypes) {
293	      try {
294	        const originalPrompt = promptsByAsset.get(assetType)![assetType.kind];
295	        // Only the evolved asset takes the evolved genome. Other images keep their own
296	        // brief: a hero must not be drawn from the background's prompt.
297	        const evolved = assetType === imageAssets[0] && solution.genome;
298	        const asset = await generator.generate(persona, assetType, {
299	          ...originalPrompt,
300	          prompt: evolved ? solution.genome : originalPrompt.prompt,
301	        });
302	        if (evaluatorProvider === "fal") {
303	          // The judge looks at images and rendered SVG; videos are judged on their brief.
304	          const imageUrl = asset.type === "image" ? asset.metadata.sourceUrl : asset.type === "svg" ? svgPreview(asset.content) : undefined;
305	          const [evaluation] = await evaluateBatch(persona, [{
306	            type: asset.type, prompt: asset.prompt, content: imageUrl ? undefined : asset.content,
307	            purpose: assetType.purpose, metadata: asset.metadata,
308	          }], (system, user) => judgeWithFal(system, user, {
309	            model: config.evaluator.model, apiKey: config.evaluator.apiKey, temperature: config.evaluator.temperature, imageUrl,
310	          }), config.evaluator);
311	          evaluations.push(evaluation);
312	          finalScores[asset.id] = evaluation;
313	        }
314	        if (evaluatorProvider === "typesafe" || evaluatorProvider === "notorganic") {
315	          const [evaluation] = await evaluateBatch(persona, [{
316	            type: asset.type, prompt: asset.prompt, content: asset.content,
317	            purpose: assetType.purpose, metadata: asset.metadata,
318	            suite: finalAssets.map(a => ({ type: a.type, purpose: a.metadata.assetPurpose, prompt: a.prompt, metadata: a.metadata, path: a.content })),
319	            judgeContext,
320	          }], async () => { throw new Error("Unexpected OpenAI evaluator selection"); }, config.evaluator);
321	          evaluations.push(evaluation);
322	          finalScores[asset.id] = evaluation;
323	          if (evaluation.gate?.accepted === false) continue;
324	        }
325	        finalAssets.push(asset);
326	      } catch (error) {
327	        log(`Failed to generate ${assetType.kind}: ${error instanceof Error ? error.message : String(error)}`);
328	        if (assetType.kind === "video" || evaluatorProvider === "typesafe" || evaluatorProvider === "notorganic" || config.generation.imageProvider === "notorganic") throw error;
329	      }
330	    }
331	  }
332	
333	  // Categorize by type
334	  const svgs = finalAssets.filter((a) => a.type === "svg");
335	  const images = finalAssets.filter((a) => a.type === "image");
336	  const videos = finalAssets.filter((a) => a.type === "video");
337	
338	  const duration = Date.now() - startTime;
339	
340	  log(`\n✅ Asset suite complete for "${persona.name}"`);
341	  log(`   Generated: ${svgs.length} SVGs, ${images.length} images, ${videos.length} videos`);
342	  log(`   Time: ${(duration / 1000).toFixed(1)}s`);
343	
344	  return {
345	    persona,
346	    assets: { svgs, images, videos },
347	    archive,
348	    evaluations,
349	    candidates,
350	    finalScores,
351	    metadata: {
352	      generationDuration: duration,
353	      totalIterations: config.qd.iterations,
354	      coverage: archive.coverage,
355	    },
356	  };
357	}
358	
359	function createArchive(config: QDConfig) {
360	  const cells = new Map<string, QDSolution<string>>();
361	  return {
362	    cells,
363	    descriptors: config.features,
364	    coverage: 0,
365	    maxQuality: 0,
366	    averageQuality: 0,
367	  };
368	}
