2	 * Layers: a subject cut out of an image, and the scene behind it.
3	 *
4	 * Creating and editing are separate roles. Whichever model drew an image, SAM 3
5	 * finds its subject by name, resvg turns the mask into the masks an edit needs,
6	 * and Ideogram repaints, all on one FAL_KEY:
7	 * https://fal.ai/models/fal-ai/sam-3/image and
8	 * https://fal.ai/models/fal-ai/ideogram/v3/edit
9	 *
10	 * Masks follow Ideogram's convention, black repainted and white kept
11	 * (https://developer.ideogram.ai). `EDIT_COLOR` flips every mask at once.
12	 */
13	import { mkdirSync, readFileSync, writeFileSync } from "node:fs";
