172	interface Source { path: string; sourceUrl?: string }
173	interface SamOutput { masks?: Array<{ url?: string }>; metadata?: Array<{ index?: number; score?: number | null }>; scores?: Array<number | null> }
174	
175	/** One segmentation per image and subject list, shared by every child editing that image. */
176	const segmentations = new Map<string, Promise<SubjectMask | undefined>>();
177	
178	/** The first named subject that SAM can cut out cleanly, or undefined. */
179	export function segmentSubject(image: Source, subjects: string[], cfg: LayerConfig): Promise<SubjectMask | undefined> {
180	  const key = [image.path, cfg.segmentModel, ...subjects].join("\n");
181	  const cached = segmentations.get(key);
182	  if (cached) return cached;
183	  const pending = findSubject(image, subjects, cfg);
184	  segmentations.set(key, pending);
185	  // A failure is not remembered, so a later edit can try again.
186	  pending.catch(() => segmentations.delete(key));
187	  while (segmentations.size > 32) segmentations.delete(segmentations.keys().next().value!);
188	  return pending;
189	}
190	
191	async function findSubject(image: Source, subjects: string[], cfg: LayerConfig): Promise<SubjectMask | undefined> {
192	  const source = await nativePng(readFileSync(image.path));
193	  if (!source || !subjects.length) return undefined;
194	  const imageUrl = await falImageInput(image.path, { key: cfg.falKey, sourceUrl: image.sourceUrl });
195	  for (const subject of subjects.slice(0, MAX_SUBJECTS)) {
196	    const result = await falRun<SamOutput>(cfg.segmentModel, {
197	      image_url: imageUrl,
198	      prompt: subject,
199	      apply_mask: false,
200	      output_format: "png",
201	      return_multiple_masks: true,
202	      max_masks: 3,
203	      include_scores: true,
204	    }, { key: cfg.falKey, timeoutMs: 180_000, pollIntervalMs: cfg.pollIntervalMs });
205	    const masks = (result.masks ?? [])
206	      .map((mask, i) => ({ url: mask?.url, score: result.metadata?.find((m) => m.index === i)?.score ?? result.scores?.[i] ?? undefined }))
207	      .sort((a, b) => (b.score ?? 0) - (a.score ?? 0));
208	    for (const candidate of masks) {
209	      if (!candidate.url || (typeof candidate.score === "number" && candidate.score < MIN_MASK_SCORE)) continue;
210	      const mask = normalizeMask(await falDownloadBytes(candidate.url, 32 * 1024 * 1024), source.width, source.height);
211	      if (mask && mask.coverage >= COVERAGE.min && mask.coverage <= COVERAGE.max) {
212	        return { ...mask, subject, ...(typeof candidate.score === "number" ? { score: candidate.score } : {}) };
213	      }
214	    }
215	  }
216	  return undefined;
217	}
